The issue is `snapshot` is assigned in the if and used in the lambda → not effectively final. Let me restructure.

arguments.command:
cd /workspace/submission/src/offline && python3 - <<'EOF'
p='ReceiveAudit.java'
s=open(p).read()
old = """    private void addAckRange(int level, long start, long end, Txn txn) {
        IntervalSet snapshot = txn.ackSnapshots.get(level);
        if (snapshot == null) {
            snapshot = ackRanges[level].copy();
            txn.ackSnapshots.put(level, snapshot);
            txn.journal.add(() -> ackRanges[level].restore(snapshot));
        }
        ackRanges[level].add(start, end);
    }"""
new = """    private void addAckRange(int level, long start, long end, Txn txn) {
        if (!txn.ackSnapshots.containsKey(level)) {
            IntervalSet snapshot = ackRanges[level].copy();
            txn.ackSnapshots.put(level, snapshot);
            txn.journal.add(() -> ackRanges[level].restore(snapshot));
        }
        ackRanges[level].add(start, end);
    }"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
